#!/bin/bash
cd "$(dirname "$0")/../.."
node scripts/portraits/select-source.js --slug jermaine-o-neal --url 'https://cdn.nba.com/manage/2025/05/GettyImages-2820782jo.jpg' --page 'https://www.nba.com/news/most-rebounds-in-a-playoff-game-indiana-pacers' --license 'unknown (Getty Images / NBAE via NBA.com)' --author 'Getty Images / NBAE' --date 'c. 2002-04 (IND at PHX, America West Arena; Getty id 2820782, caption unreadable: gettyimages.com 403)' --crop 512,0,640 --scores 3,3,3,2,2,2,1 --energy 6.5 --vs-mccain 'matches (standing on court during a stop, eyes up off-camera, lips parted, sweaty)' --jersey 'IND navy pinstripe road #7, c. 2002-04' --concerns 'renamed nba.com file (jo suffix), no Getty caption check, but clearly O'"'"'Neal in IND #7; exact date unverified; yellow headband; hair touches top of frame' --alt 'https://cdn.nba.com/manage/2025/05/GettyImages-78535523jo.jpg (IND navy road c. 2007-08 at NYK, full-body, face ~110px, neutral, energy ~4)' --alt 'https://upload.wikimedia.org/wikipedia/commons/2/2f/Jermaine_O%27Neal_cropped.jpg (CC BY-SA 2.0 Keith Allison, BOS green 2011, looking down, energy ~4, not IND)'
node scripts/portraits/select-source.js --slug larry-hughes --url 'https://cdn.nba.com/manage/2025/09/GettyImages-13720058721.jpg' --page 'https://www.nba.com/news/washington-wizards-single-season-steals-per-game-leaders' --license 'unknown (Getty Images / NBAE via NBA.com)' --author 'Getty Images / NBAE' --date 'c. 2002-05 (WAS at LAC, Staples Center; article caption "Larry Hughes is the SPG leader for the Wizards"; Getty caption unreadable: gettyimages.com 403)' --crop 930,0,560 --scores 2,2,3,2,2,2,1 --energy 6 --vs-mccain 'slightly lower (crouched in a defensive stance, eyes up and off-camera, lips parted mid-breath)' --jersey 'WAS light-blue road #20, c. 2002-05' --concerns 'face ~200px (1920px web copy), slightly soft; body leans into the left of the crop; head band; exact date unverified' --alt 'https://upload.wikimedia.org/wikipedia/commons/8/8a/Larry_Hughes_Apr_2007.jpg (CC BY-SA 2.0 Keith Allison, CLE navy road Apr 2007, full-body dribble, face ~120px, neutral, energy ~4, not WAS)' --alt 'https://upload.wikimedia.org/wikipedia/commons/6/66/Larry_Hughes_Bulls.jpg (CC BY-SA 2.0, CHI white 2008, tiny face at a free-throw lane, not WAS)' --needs-review 'face ~200px, under the 250px bar'
node scripts/portraits/select-source.js --slug kenyon-martin --url 'https://cdn.nba.com/teams/legacy/www.nba.com/nets/sites/nets/files/bkn_1819_sc_top25_11-martin_910x575.jpg' --page 'https://www.nba.com/nets/news/2018/08/28/nets-all-time-top-25-no-11-kenyon-martin' --license 'unknown (NBA.com / Brooklyn Nets graphic; Getty Images / NBAE photo)' --author 'Getty Images / NBAE (Brooklyn Nets graphic)' --date 'c. 2002-04 (NJN navy road, undated; used in the Nets All-Time Top 25 No. 11 feature)' --crop 575,0,335 --scores 1,1,3,2,2,2,1 --energy 7 --vs-mccain 'matches (ball held high at his shoulder, eyes locked off-camera, lips pushed out in concentration)' --jersey 'NJN navy road #6, c. 2002-04' --concerns 'publisher graphic (Nets Top 25 card; text panel on the left, outside the crop); face ~145px in a 910px file, soft and compressed; wristband and raised arm fill the lower crop; date unverified. The earlier depth-and-career round left him unrecorded for lack of an NJN photo; the DEN alt is far sharper if the jersey can give' --alt 'https://upload.wikimedia.org/wikipedia/commons/a/a4/Kenyon_Martin_Nuggets.jpg (CC BY-SA 2.0 Keith Allison, Jan 25 2011 DEN at WAS, light-blue road #4, ~900px face, looking off-camera with lips parted, energy 6, sharp, but Nuggets not NJN; crop 0,0,1600)' --alt 'https://cdn.nba.com/teams/legacy/www.nba.com/nets/sites/nets/files/1gettyimages-632348.jpg (NJN white 2002 R1 G5 vs IND, celebrating with arms up, tiny face)' --needs-review 'publisher graphic, face ~145px and soft; sharper DEN 2011 Commons alt exists'
node scripts/portraits/select-source.js --slug richard-jefferson --url 'https://cdn.nba.com/teams/legacy/www.nba.com/nets/sites/nets/files/bkn_1819_sc_top25_8-jefferson_910x575.jpg' --page 'https://www.nba.com/nets/news/2018/09/04/nets-all-time-top-25-no-8-richard-jefferson' --license 'unknown (NBA.com / Brooklyn Nets graphic; Getty Images / NBAE photo)' --author 'Getty Images / NBAE (Brooklyn Nets graphic)' --date 'c. 2002-05 (NJN white home, Continental Airlines Arena, undated; used in the Nets All-Time Top 25 No. 8 feature)' --crop 395,0,345 --scores 2,1,3,2,2,2,1 --energy 6.5 --vs-mccain 'matches (driving with the ball, eyes down-left on the play, lips parted mid-breath)' --jersey 'NJN white home #24, c. 2002-05' --concerns 'publisher graphic (Nets Top 25 card; text panel on the left, outside the crop); face ~190px in a 910px file, light grain; eyes look down rather than up; date unverified' --alt 'https://cdn.nba.com/manage/2018/10/richard-jefferson.jpg (renamed nba.com, CLE white c. 2016, at the free-throw line looking up, lips parted, energy 6.5, sharp ~450px face, but Cavaliers and late career)' --alt 'https://cdn.nba.com/teams/legacy/www.nba.com/nets/sites/nets/files/3gettyimages-74078642.jpg (NJN white, 2007 R1 G6 vs TOR, mid-drive, tiny face)' --needs-review 'publisher graphic, face ~190px'
node scripts/portraits/select-source.js --slug james-posey --url 'https://upload.wikimedia.org/wikipedia/commons/5/5e/Darius_Songaila_and_James_Posey.jpg' --page 'https://commons.wikimedia.org/wiki/File:Darius_Songaila_and_James_Posey.jpg' --license 'CC BY-SA 2.0' --author 'Keith Allison' --date '2008-01-13 (Celtics at Wizards, Verizon Center)' --crop 1385,330,1080 --scores 3,3,1,2,2,1,0 --energy 5 --vs-mccain 'lower (side-eye glance off-camera, brow set, lips pressed together)' --jersey 'BOS green road #41, 2007-08 — NOT the wanted MEM' --concerns 'FLAG: Celtics, not MEM (no in-game Grizzlies photo of Posey found on Commons, Openverse or nba.com; the only MEM frame is a tiny far-court jump ball); energy 5, mouth closed; Darius Songaila stands just left of the crop; head sits left of centre' --alt 'https://upload.wikimedia.org/wikipedia/commons/c/ce/James_Posey_Hornets.jpg (CC BY-SA 2.0 Keith Allison, NOH 2009, ~300px face, but squinting mouthguard grin while pointing, eyes nearly shut)' --alt 'https://upload.wikimedia.org/wikipedia/commons/7/79/Lakers_Grizzlies_200304.jpg (CC BY-SA 2.0, MEM navy road Nov 23 2003 at LAL, jump ball from the stands, face ~15px)' --needs-review 'BOS not MEM; energy 5 (below band)'
